  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "A close N-methyl-tetrahydropyridine analogue freely crosses the BBB in rodents and non-human primates after i.v. injection, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A structurally related N-methyl-tetrahydropyridine PET tracer shows high, rapid brain uptake in rats, demonstrating efficient BBB penetration for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "An N-methyl-piperidine/tetrahydropyridine analogue shows extremely high brain uptake (>14% ID/g) in mice, confirming strong CNS exposure for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A tetrahydropyridine-containing muscarinic agonist rapidly enters monkey brain with 5-10% of the intravenous dose reaching the brain, providing quantitative evidence of meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A related tetrahydropyridine analogue achieves a 1:1 brain-to-blood ratio in rat microdialysis, indicating substantial CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A high-transfer CNS-positive reference has a logBB of 0.99 in rats, reinforcing that molecules with similar physicochemical features can achieve robust brain distribution.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate robust CNS penetration across multiple species and assay types, and the query shares the N-methyl-tetrahydropyridine scaffold plus favorable physicochemical properties; therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct experimental measurement exists for the exact query molecule.",
    "Efflux transporter liability was not directly tested for the query, though the analogue evidence does not indicate a barrier.",
    "Partial ionization at physiological pH may modulate permeability but is not sufficient to overturn the strong supportive evidence."
  ],
